export interface Passage {
  id: string
  title: string
  content: string
  source: string
}

export interface ScoringCriterion {
  grade: string
  range: string
  description: string
}

export interface ExamQuestion {
  id: number | string
  title: string
  questionText: string
  targetLength: string
  minChars: number
  maxChars: number
  recommendedTime: string
  points: number
  passages: Passage[]
  scoringCriteria: ScoringCriterion[]
  keyArguments: string[]
  modelAnswer: string
}

export interface HongikExamDetail {
  id: string
  title: string
  year: string
  targetFaculty: string
  totalTime: number
  totalLength: string
  level: string
  type: '기출문제' | '모의논술' | '예상문제'
  summary: string
  questions: ExamQuestion[]
}

