          "content": "마을 어귀에 낯선 행색의 나그네가 나타났을 때, 노인들은 밥상을 내어주면서도 눈동자에는 짙은 경계의 빛을 거두지 않았다. 겉으로는 조상 대대로 내려온 미풍양속이라며 헛간 한구석을 잠자리로 내어주었지만, 밤새 곳간 문에 굵은 빗장을 걸어 잠그고 숟가락 하나가 사라질까 감시를 늦추지 않았다. 마을 청년들은 나그네의 어눌한 사투리와 기이한 복장을 흉내 내며 낄낄거렸고, 며칠 뒤 닭 한 마리가 없어지자 물증도 없이 나그네를 도둑으로 몰아세웠다. 쫓겨나는 나그네를 향해 사람들은 ‘은혜를 모르는 놈’이라며 침을 뱉었다. 마을 사람들의 환대는 손님을 동등한 인간으로 받아들인 것이 아니라, 시혜적인 자비를 베풂으로써 자신들의 도덕적 우월감을 확인하고, 언제든 위험 요소로 규정하여 추방할 수 있는 낙인의 권력을 휘두르는 위선적인 경계 짓기에 불과했다.",
