      "modelAnswer": "공동체가 낯선 타자를 맞이하는 방식은 그 문명의 윤리적 성숙도를 드러낸다. 제시문 (가)는 조건 없는 열린 마음인 ‘무조건적 환대’와 공동체 안전을 위해 선별하고 통제하는 ‘조건부 환대’ 사이의 필연적 긴장을 설명한다. 이 두 환대의 줄다리기는 사회 여러 영역에서 상반된 양상으로 나타난다.\\n\\n(나)는 조건부 환대가 배타적 폭력으로 변질되는 양상을 보여준다. 마을 사람들은 나그네에게 시혜적인 잠자리를 내주었지만 끊임없이 도둑으로 의심했고, 결국 사소한 일로 추방하며 낙인을 찍었다. 이는 환대를 가장한 채 도덕적 우월감을 누리고 내부의 결속을 다지기 위해 타자를 희생양 삼는 위선적 경계 짓기이다. 반면 (다)는 타자와의 만남이 경계를 허물고 새로운 가치를 창출하는 예술적 실천을 제시한다. 디아스포라 예술은 이질적인 문화의 충돌을 혼종성으로 승화하여 중심과 주변의 배타적 경계를 무너뜨린다. 즉 환대는 타자를 내 틀에 가두는 것이 아니라 나 자신의 정체성을 새롭게 확장하는 계기가 된다. 한편 (라)는 현대 사회가 이주민을 노동력이라는 경제적 도구로만 환대하며 동화를 강요하는 현실을 비판하고, 다름을 인정하는 포용적 시민권 보장의 필요성을 역설한다.\\n\\n따라서 다문화 사회에서 진정한 공존을 이루기 위해서는 타자를 도구화하거나 동질화를 강요하는 배타적 경계를 허물어야 한다. (나)와 같은 의심과 낙인을 거두고, (다)처럼 타자와의 차이를 배움과 자기 갱신의 기회로 삼아야 한다. 나아가 (라)의 지적대로 이주민을 시혜의 대상이 아닌 온전한 동등한 시민으로 포용하는 제도적 환대를 실천할 때 비로소 지속 가능한 다원주의 공동체가 완성될 수 있다. (858자)"
