          "content": "2024년 8월, 헌법재판소는 청소년과 아기 등 청구인들이 제기한 ‘기후위기 헌법소원’에서 ｢탄소중립기본법｣ 제8조 제1항에 대해 전원일치로 ‘헌법불합치’ 결정을 내렸다. 해당 조항은 2030년까지 온실가스를 2018년 대비 40% 감축한다고 규정하면서도, 2031년부터 2050년 탄소중립 목표 시점까지의 구체적 감축 목표를 법률에 전혀 규정하지 않았다. 헌재는 “2031년 이후의 정량적 기준을 법제화하지 않은 것은 2030년까지의 감축 부담을 완화하는 대신, 미래 세대에게 불균등하게 과도한 감축 부담을 떠넘기는 것으로서 국가의 기본권 보호 의무를 위반하여 미래 세대의 환경권과 생명권을 침해한다”라고 판시했다. 정치권이 단기적인 선거 표심과 기업의 이해관계에 휘둘려 당장의 고통 분담을 회피하고, 미래의 시민들에게 기후 재앙을 떠넘겨 온 입법적 태만이 사법적으로 위헌임을 확인한 역사적 판결이다.",
