      "modelAnswer": "능력주의는 공정의 이상으로 포장되어 있으나, 불평등을 정당화하는 강력한 이데올로기로 작동한다. 제시문 (마)는 능력주의가 출발선의 불평등을 은폐한 채 승자에게는 모든 것이 제 능력 덕이라는 오만을, 패자에게는 무능력이라는 굴욕을 안기며 불평등을 도덕적으로 정당화한다고 비판한다.\\n\\n이러한 구조적 모순은 교육과 입시 현실에서 적나라하게 드러난다. 제시문 (바)에 나타나듯, 고소득층 부모의 막대한 사교육비 투자는 자녀의 명문대 진학과 고소득 직업 세습으로 이어져 ‘부모의 부’가 ‘자녀의 능력’으로 둔갑한다. 또한 제시문 (사)가 지적하듯, 단일 지필고사 점수로 줄을 세우는 방식은 시비만 없애는 ‘형식적 공정’일 뿐, 성장 환경의 격차를 무시하여 취약계층의 계층 이동 사다리를 붕괴시키는 ‘실질적 불공정’을 낳는다.\\n\\n이 문제를 해결하기 위해서는 제시문 (아)가 제안한 왈저의 ‘복합 평등’을 제도화해야 한다. 학벌이나 시험 성적이 다른 삶의 영역과 인간적 존엄까지 독점적으로 지배하는 전제를 차단해야 한다. 첫째, 교육의 출발선 격차를 보정하기 위해 ‘지역균형선발제’와 ‘사회통합전형’을 대학과 양질의 일자리에 대폭 의무화해야 한다. 둘째, 시험 점수가 낮거나 명문대를 나오지 않았더라도 사회에 기여하는 모든 노동자가 안정된 생활을 누릴 수 있도록 직종 간 임금 격차를 완화하고 사회적 필수 노동의 가치를 재평가해야 한다. 학벌이라는 단일 잣대를 넘어 다양한 재능과 노동이 동등하게 존중받을 때 진정한 공정이 실현될 수 있다. (864자)"
