            "content": "자신이 관심 있는 주제나 분야에서 출발하는 것 외에 또 다른 방법도 있습니다. 이를테면 저는 오에 겐자부로의 『개인적인 체험』을 좋아합니다. 주인공 버드의 아내는 아들을 낳습니다. 그런데 이 아이는 두개골 결손으로 뇌 일부가 빠져나온 상태로 태어납니다. 아들을 살리려면 엄청난 수술을 해야 하는데, 살아나도 식물인간이나 장애아로 살 확률이 높습니다. 반대로 만약 분유량을 조금만 줄인다면, 이 아이는 자연스럽게 죽을 겁니다. 평생 장애 아이를 돌보게 될지도 모르는 쉽지 않은 상황 앞에서 버드는 고민에 빠집니다. 아들을 죽이긴 쉽고 살리긴 어렵습니다.\n\n여행을 좋아해서 아프리카 지도를 사고, 아프리카 여행을 꿈꾸었던 젊은 아빠 버드는 절망합니다. 아들이 살아난다면 그의 계획이나 꿈은 물거품이 될 것입니다. 그는 자신의 꿈을 선택합니다. 그리고 대학 시절 여자 친구와 아프리카로 몰래 떠나려 합니다. 하지만 어느 순간 묻습니다. ‘수치스러운 짓들을 무수히 거듭하여 도망치면서 도대체 무엇을 지키려 했던 것일까? 대체 어떤 나 자신을 지켜 내겠다고 시도한 것일까?’ 그는 ‘난 이제 도망치는 건 그만둘래.’라고 생각합니다. 그는 아들을 살리려고 빗속에서 택시를 타고 질주합니다. ‘만약 내가 사고로 죽어서 아들을 살리지 못한다면 지금까지 내 삶은 말짱 무의미한 것이 될 것이다.’라고 생각하면서요.\n\n나중에 『오에 겐자부로, 작가 자신을 말하다』를 읽다 보니 그는 어려서부터 『허클베리 핀의 모험』을 좋아했고 실제로 삶에서 선택해야 할 때마다 허클베리 핀의 이 말을 읊조렸다고 합니다. “좋아, 지옥에는 내가 간다.” 저는 이 말이 『개인적인 체험』에 나오는 주인공의 선택에도 영향을 미쳤을 거란 느낌이 듭니다. 저는 곧 또다시 『허클베리 핀의 모험』을 들추어 볼 것입니다. “지옥에는 내가 간다.”란 말을 찾아서요. 이렇게 책 속의 책을 따라갈 수도 있는 것입니다.\n\n오에 겐자부로는 『신곡』 또한 좋아합니다. 저는 언제 『신곡』도 읽어야겠다고 쭉 생각하고 있었습니다. 그런데 미루어 두던 『신곡』을 실제로 읽게 된 계기는 현실에서 왔습니다. 여기서 현실에서 궁금한 것을 책에서 찾아 읽는 또 다른 목록 작성법이 나옵니다. TV에 어느 장례식장의 유족들이 나오는데, 한 어머니만은 눈물을 꾹 참고 울지 않았습니다. 어머니는 왜 울지 않느냐는 질문을 기자가 던졌던 것 같습니다. 그 어머니는 “내가 자꾸 울면 우리 아들이 좋은 데 못 간다고 해서.”라고 말하며 입술을 꼭 깨물며 눈물을 참습니다. 좋은 데는 천국이겠죠. 장례식 때 유족들은 관을 쓰다듬으며 마지막 인사를 보내면서 이렇게 말합니다. “잘 가, 천국에 가. 그곳에서 여기 일은 다 잊어버리고 부디 행복하게 살아. 그곳에서 시름 걱정 없이 살아. 아프지 말고 울지도 말고. 거기서 만나자. 먼저 가 있어.”\n\n천국의 소망이 아니면 정말 위로가 안 되는 안타까운 죽음들이 있습니다. 저 역시 장례식을 보면서 눈물을 흘렸습니다. 그러면서도 천국은 어떤 곳일까, 단테는 천국을 어떤 곳이라고 생각했을까 궁금했습니다. 결국 『신곡』을 읽었습니다. 그런데 천국은 우리가 상상하는 그런 곳이 아니었습니다. 천국에 간 사람들은 우릴 잊고 행복하게 사는 것이 아니었습니다. 그 반대로 영원한 기억 속에 있습니다. 천국에 사는 사람들은 우릴 절대로 잊지 못합니다. 우릴 항상 지켜봅니다. 우리가 탄 배가 잘못된 방향으로 가면 애가 타서 말합니다. 합창합니다. “안 돼. 그쪽이 아니야. 뱃머리를 돌려!” 우리가 사랑했던 사람들은 우리가 품었던 천국의 소망 같은 것들이 현실에서도 이루어지길 바랍니다.",
