            "content": "유럽에서는 십자군 전쟁 이후 향신료, 비단 등 동양 상품의 수요가 증대되었다. 그러나 오스만 제국이 동서 교역의 주도권을 장악하자 동양과 직접 교역하려는 욕구가 커졌다. 마르코 폴로의 『동방견문록』 등으로 동양에 관한 호기심이 증가하고 천문학, 지리학, 조선술의 발달과 나침반 사용 등으로 원양 항해가 가능해지자, 유럽인은 새로운 항로를 찾아 나섰다. 지중해를 통한 향신료 무역에서 소외되었던 포르투갈과 에스파냐는 서아프리카 해안을 돌아 새로운 항로를 개척하고자 하였다. 포르투갈의 바르톨로메우 디아스가 ‘희망봉’이라 부른 아프리카 남쪽 끝에 도착하였으며, 바스쿠 다 가마는 이슬람 상인의 도움을 받아 인도의 캘리컷에 도착함으로써 인도 항로를 개척하였다. 에스파냐의 후원을 받은 콜럼버스는 대서양 항로를 개척하여 아메리카 대륙의 서인도 제도에 도착하였다. 마젤란 일행은 대서양을 건너 태평양을 횡단하고 최초로 세계를 일주하였다.\n\n이러한 신항로 개척으로 무역의 중심지가 지중해에서 대서양 지역으로 이동하였다. 에스파냐는 아스테카와 잉카 제국을 정복한 뒤 금광·은광 개발에 몰두했는데, 아메리카에서 채굴한 많은 양의 금과 은이 유럽에 들어오면서 물가 폭등 현상이 나타났으니 이를 ‘가격 혁명’이라 한다. 포르투갈은 아프리카 항로를 개척한 후 노예무역을 시작하였는데, 이후 유럽인들이 아메리카에 대규모 플랜테이션 작물을 재배하며 부족한 노동력을 보충하기 위해 노예무역을 확대하였다. 유럽인은 총, 직물 등을 싣고 서아프리카로 향하여 흑인 노예와 교환하였으며, 흑인 노예를 태우고 아메리카 대륙으로 건너가 농장주에게 팔았다. 그리고 노예를 판매한 대금으로 설탕, 커피, 담배 등 플랜테이션 작물을 사들여 유럽으로 돌아왔다. 이렇게 유럽과 아프리카, 아메리카를 잇는 삼각 무역을 중심으로 대서양 교역이 이루어졌다.",
