            "content": "블록체인의 가장 중요한 특징 중 하나인 탈중앙화는 ‘중간 관리자 없이 모두가 함께 관리하는 시스템’을 의미한다. 우리가 흔히 사용하는 은행 시스템을 예로 들어보자. 은행은 모든 사람의 거래 기록을 혼자서 보관하고 관리하며, 거래의 사실 여부를 보증하는 유일한 기관이다. 신뢰는 은행이라는 거대한 중앙기관에 집중되어 있다. 하지만 블록체인은 이러한 방식에서 벗어나, 네트워크에 참여하는 노드들이 함께 정보를 나누어 보관하고 서로의 기록을 검증한다. 마치 모든 친구들이 똑같은 거래 장부를 하나씩 가지고 있는 것과 같다. 이 장부에는 모든 사람의 거래 내역이 기록되어 있는데, 만약 어떤 친구가 자기 장부의 내용을 몰래 고치려고 해도, 다른 친구들이 가진 수많은 장부의 내용과 달라서 금방 탄로가 난다. 또한 중앙 서버가 해킹되거나 특정 관리자의 실수로 데이터가 사라지더라도, 다른 기록들이 이를 보완하여 전체 시스템은 완전하게 유지된다. 결과적으로 블록체인은 신뢰의 초점을 중앙기관에서 개인과 집단의 합의로 이동시킨다. 과거에는 은행과 같은 중앙기관이 거래를 보장해 주었지만, 블록체인에서는 참여자들 간의 합의를 통해 거래의 진위가 판단되고 신뢰가 형성된다. 즉, 특정한 중앙기관에 대한 맹목적인 신뢰 없이도 기술적인 합의를 통해 믿을 수 있는 거래가 가능해지는 새로운 질서이다.",
