            "content": "과학기술의 발전 덕분에 우리가 더 나은 세상을 향해 멈출 수 없는 추세로 전진하고 있다고 이야기한다. 그러나 역사적으로 발명과 혁신이 딴판의 결과를 불러온 사례가 많다. 예를 들어, 중세 시대 농업 기술 발달은 생산량의 증가에도 불구하고 인구의 90퍼센트에 달하던 농민에게는 아무런 이득을 가져다 주지 않았다. 기술 낙관주의가 옳은 측면도 있다. 특히 디지털 기술이 과학지식의 발달 과정을 혁명적으로 바꾼 점이 그러하다. 인류가 쌓아온 방대한 지식이 이제 우리 손이 닿는 곳에 가까이 존재한다. 하지만 이러한 진보를 바탕으로 더 많은 과학적 발견이 이루어지고 그것이 나아가 수십억 인구의 삶을 더 나아지게 만드는 쪽으로 쓰이게 하려면 과학기술의 방향을 바꾸어야 한다. 이는 맹목적인 기술 낙관주의를 경계하고 과학기술의 혁신을 활용하는 새로운 방향을 설정하는 데서 시작해야 한다. 새로운 과학기술이 광범위한 번영으로 이어지는 것은 결코 자동적인 과정이 아니다. 그렇게 되느냐 아니냐는 정치적·경제적 선택에 달려있다. 순전히 기술 공학적 의미에서 무엇이 합리적인지가 꼭 결정적인 요소인 것은 아니라는 말이다. 서로 다른 선택지는 서로 다른 집단에 이익을 가져다주므로 선택은 근본적으로 권력의 문제이다.",
