            "title": "노갈레스의 운명과 포용적 제도",
            "content": "미국과 멕시코의 접경지대에는 ‘노갈레스’라는 도시가 있다. 노갈레스는 원래 멕시코 국경에 있는 작은 마을에 불과했는데, 1853년 미국 정부가 멕시코 정부로부터 노갈레스의 일부를 매입한 후, 1994년에 거대한 장벽을 세움으로써 한쪽은 멕시코 소노라주 노갈레스, 다른 한쪽은 미국 애리조나주 노갈레스로 나누어지게 된다. 국경선을 맞댄 쌍둥이 도시지만 두 도시의 운명은 판이하다. 미국 노갈레스 주민들은 멕시코 노갈레스 주민들보다 평균 세 배 이상의 돈을 벌고 있으며, 멕시코 주민들은 누리지 못하는 다양한 교육, 의료혜택, 복지 등의 공공 서비스 및 인프라를 제공받고 있다. 이러한 차이를 만드는 것은 각 국가의 제도이다. 멕시코에서는 힘 있는 정치 세력과 독점 기업 간의 오래된 유착관계를 방치하여, 기업 간 공정한 경쟁을 막고 새로운 기업의 시장 진입을 어렵게 하는 제도가 만들어졌다. 이러한 착취적 제도는 탈세, 횡령과 같은 부정부패를 성행하게 하며, 정당한 근로의 기회와 대가를 보장하지 않아 사람들 간 극심한 빈부 격차를 초래했다. 이에 반해, 미국은 아이디어에 대한 재산권을 보호하고, 특정 기업의 독점을 허용하지 않는 등 합당한 인센티브(경제적 유인)와 공평한 기회를 제공하는 포용적 제도를 취함으로써 기업가 정신을 보장하고 이를 통해 과학기술의 혁신과 근로자의 처우개선을 바탕으로 한 경제 성장을 이룰 수 있었다.",
