            "content": "시민은 다양한 방법을 통해 정치 과정에서 자신의 요구를 표출하고 이를 정책에 반영하려고 한다. 시민의 적극적인 정치 참여는 국가 권력에 의한 정책 결정에 정당성을 부여하는 한편, 감시와 비판을 통해 국가 권력의 남용을 방지할 수 있다. 소규모의 인터넷 카페로 시작하여 회원 4만 4천여 명의 시민 단체로 급성장한 ‘미대촉’(미세먼지 대책을 촉구합니다)이 그 대표적인 사례이다. 이 단체의 활동을 주도하는 사람들은 전문적인 사회 운동가가 아니라 평범하게 자녀를 키우는 학부모이다. 이들은 환경부와의 면담, 집회와 토론회, 서명 운동 등 다양한 활동을 통해서 오랫동안 지연되고 있던 ‘미세먼지 대책 특별법’의 신속한 발의를 촉구하였다. 그 결과, 학교 등에 공기 정화시설 설치, 어린이 통학 차량의 친환경차 전환 등의 내용이 포함된 「미세먼지 저감 및 관리에 관한 특별법」이 2018년에 국회를 통과하여 시행되었다.",
