        "modelAnswer": "(가)~(다)의 공통점은 자신의 욕구 충족을 위한 행동이 다수에 의해 반복됨으로써 계획하지 않은 결과가 나타난다는 것이다. 개인들은 모두 자신의 욕구 충족을 위한 선택을 한다. (가)에서는 경제적 이익을 추구하고, (나)에서는 사회적 이미지 유지를 위해 여성을 가리키는 고상한 표현을 선택하며, (다)에서는 목적지에 빨리 도착하기 위해 내비게이션의 빠른 경로를 선택한다. 그러나 그러한 선택이 다수에 의해 반복된 결과, 거시적으로 개인이 의도하지 않은 결과인 공공의 이익(가), 고상한 표현의 의미 하락(나), 교통 체증(다)이 도출된다.\n\n(가)~(다)의 차이점은 결과의 긍·부정성, 그리고 개인의 의도와 결과 사이의 관계에서 발견된다. (가)의 결과인 공공의 이익은 긍정적이나 (다)의 결과인 교통 체증은 부정적이며, (나)의 결과인 단어의 의미 변화 현상은 그 자체가 사람들에게 미치는 영향의 긍·부정성을 따지기 어렵다. 한편 (가)의 결과는 개인의 의도인 이익 추구와 상충하지 않으나, (나), (다)의 결과는 고상한 단어를 써서 여성을 예우하고 타인에게 긍정적 이미지를 주려던, 또 목적지에 빠르게 도착하려던 개인의 본래 의도와 상충된다.\n\n(라)는 (가)~(다)에서 나타나는 공통 구조를 다른 주체가 의도적으로 이용하는 방식으로 (가)~(다)와 연결된다. 즉 B국은 국민들의 퇴직 후 재정적 안정이라는 결과를 도출하기 위해 저축 프로그램 가입을 기본값으로 설정했고, 개개인이 선택을 바꿀 때 생길 수 있는 손실과 부담을 피하려는 욕구에 따라 행동하면 그 결과가 모여 국민들의 노후 대비라는 목표를 달성할 수 있도록 했다. 이는 (가)~(다)에 나타난 개인의 행동 원리와 그것이 반복됨으로써 나타날 수 있는 거시적 결과를 우연히 얻은 것이 아니라, 처음부터 예측하여 의도적으로 활용한 사례에 해당한다. (867자)"
