            "content": "기록은 우리 주변에서 쉽게 접할 수 있다. 달력 한 귀퉁이에 적은 것도 기록이고 노트를 빼곡하게 채우는 것도 기록이라 부른다. 하지만 기록에 대한 체계적인 관리를 위해서는 보다 세밀한 정의가 필요하다. 우리나라에서는 기록을, “조직이나 개인이 법적 의무를 수행하거나 업무를 처리하는 과정에서 증거와 정보로써 생산, 접수, 유지하는 정보.”라 규정한다. 그러나 이러한 규정에 해당한다고 하여 모든 기록이 가치 있는 것은 아니다. 기록이 그 생산·관리 및 이용 가치를 인정받기 위해서는 몇 가지 요소를 갖추어야 하는데, 그중 첫 번째가 진본성(眞本性 authenticity)이다. 진본성은 어떤 기록이 위조되지 않은 원래 그대로의 것임을 의미한다. 쉽게 말해 ‘이’ 『태종실록』이 조선 실록청에서 편찬한 것이 맞는지, ‘저’ 『난중일기』가 이순신 장군이 쓴 일기가 진짜 맞는지를 따지는 것이다. 두 번째 요소로 무결성(無缺性 integrity)을 들 수 있다. 무결성은 기록이 훼손, 손실, 변조 등에 의하여 변경되지 않고 완전한 상태를 유지하고 있음을 말한다. 다만 기록이 생산된 후 그 물리적 요소가 변했다고 해서, 예를 들어 종이 기록의 잉크가 흐려졌거나 모서리가 떨어져 나갔다고 해도 무결성이 손상되었다고 보지는 않는다. 그러나 몇 면이 없어졌거나 없어진 면이 공증 서명 부분이라면, 무결성에 중대한 영향을 미치는 변경에 해당한다. 한편 데이터와 같은 전자 기록의 무결성은 상대적인 개념으로, 기록의 본질적인 성격이 변하지 않았는지로 판단한다. 디지털 정보의 무결성을 유지하기 위해서는 어느 정도의 변형은 불가피하다는 모순이 존재하기 때문이다. 즉, 전자 기록은 그 기록이 담고 있는 의미가 변하지 않는 한, 변경되지 않은 완전한 것으로 간주할 수 있다. 따라서 그 내용과 형태의 요건이 동일하다면 디지털 정보를 구성하는 비트스트림(bit stream) 등의 물리적 속성이 변경되어도 기록의 무결성은 유지될 수 있다. 또한 가치 있는 기록의 구성 요소로 이용가능성(usability)도 있다. 이는 기록의 위치를 찾을 수 있고 기록이 검색될 수 있으며, 보일 수 있고 해석될 수 있음을 의미한다. 기록을 가치 있게 이용하려면 이용자가 그것을 볼 수 있고 이해할 수 있어야 하기 때문이다. 특히 전자 기록의 이용가능성을 위해서는 기술환경이 변화해도 이를 보거나 이해할 수 있는 방식으로 기록이 유지되어야 한다.",
