            "content": "민주주의는 국민주권에 따라 대다수의 시민들에게 직접적이든 간접적이든 간에 국가의 중요한 의사결정에 참여할 수 있는 권리가 있다고 본다. 참정권이라 불리는 이런 기본권에 근거하여 민주주의 시민들은 투표권 및 선거권을 가진다. 보통선거를 통해 온건한 국민 주권주의를 실현한 현대의 민주주의 국가는 ‘대의 민주제’를 그 바탕으로 하고 있다. 국민이 선거를 통해 대표자를 선출하고 선출된 대표자들이 국민의 주권을 위임받아 국가의 정책을 결정하고 집행하는 것이다. 민주 정치 과정에서 ‘선거’는 국민이 주권을 행사하는 가장 중요한 수단으로, 다수 유권자의 선택은 매우 중요하다. 그렇기에 유권자는 자신이 선택하는 정당이나 인물, 정책에 대해 충분하고도 정확한 정보를 가져야 한다. 또한 민주 시민은 기본권으로 인간으로서의 존엄과 가치에 대한 권리를 지닌다. 행복추구권은 이를 보장하기 위한 권리로, 인간으로서 누려야 할 행복을 충족할 수 있는 모든 자유와 권리의 내용을 담고 있는 포괄적 기본권이다. 이러한 인간의 존엄과 가치 및 행복추구권하에서 민주 시민은 국가에 시민의 안전, 생명과 재산의 보호, 인권의 보호, 사회 보장과 사회 복지의 증진, 깨끗한 환경, 공공재의 효율적인 관리와 제공 등을 요구하고 보장받을 권리를 가지게 된다.",
