            "content": "최근 우리 사회에 중요한 이슈로 대두되고 있는 ESG에서는 기업의 사회적 책임을 강조한다. 기업의 지속적인 경영을 의미하는 ESG는 기업의 지속 가능성이 환경 및 사회의 지속 가능성과 상호 관계에 있음을 강조하며, 환경과 사회에 대한 기업의 관심과 투자에 가치를 둔다. 즉, 기업의 단기적 이윤 증가보다 사회 전체의 이익 증진이 기업의 양적 질적 발전을 가능하게 해준다는 것이다. ESG를 실천하는 기업은 근로자가 안전하고 행복하게 일할 수 있는 근무 조건을 보장하여 근로자 삶의 만족도를 높임과 동시에, 주위의 사회적 환경 개선과 자연적 환경의 보존에 힘씀으로써 공동체 구성원들의 삶의 질이 향상되도록 한다. 최근 한 연구에서는 지역 신문사의 언론 활동이 기업 ESG 활동과 관계가 있음을 보여주었다. 이 연구는, 2000년에서 2017년 사이 미국에서 총 33개의 지역 신문사가 문을 닫았는데 지역 소식을 다루던 이들 신문사의 폐업이 기업 ESG 실천에 부정적인 영향을 끼쳤다고 분석했다. 지역 신문사 폐업이 있었던 지역의 공장들(A그룹), 지역 신문사 폐업이 없었던 지역의 공장들(B그룹), 이 두 그룹의 공장들을 대상으로 탄소 배출량과 ESG 관련 규정 위반 사례 건수를 비교·분석한 결과, 폐업 후 A그룹이 B그룹에 비해 탄소배출량은 약 18.3%, ESG 관련, 즉, 산업현장안전, 노사관계, 근로환경 등의 규정 위반 사례 건수는 약 15.2% 높게 나타났다.",
