            "content": "2020년 미국 대통령 선거 당시 미국의 방송사 폭스 뉴스(Fox News)는 투표 기계 및 선거 소프트웨어 회사인 도미니언 보팅 시스템(Dominian Voting Systems)이 소프트웨어 시스템 조작을 통해 민주당 후보의 득표 수를 늘렸다는 내용을 반복적으로 보도했다. 이에 도미니언 보팅 시스템은 2021년 3월 해당 보도가 허위 사실이라며 폭스 뉴스를 상대로 한화 약 1조 8천억원 규모의 소송을 제기했다. 재판 중에 폭스 뉴스가 보도 내용이 허위임을 내부적으로 인지하고 있었음에도 이를 방송했다는 증거가 드러났고, 결국 폭스 뉴스는 2023년 3월, 허위 정보 유포로 인한 명예훼손 합의금으로 도미니언 보팅 시스템에 한화 약 1조원에 가까운 금액을 지급하였다. 이것은 미국 언론사 대상 명예훼손 소송 중 규모가 매우 큰 사례로 기록된다.",
