            "content": "인간 생활 양식의 총체인 문화는 고정되어 있지 않고 지속해서 변화한다. 한 사회의 문화가 새로운 요소의 등장에 영향을 받아 변하는 현상을 문화 변동이라 한다. 문화 변동을 일으키는 사회 내적 요인은 발명과 발견이 대표적이다. 발명은 이전에 존재하지 않았던 것을 새롭게 만들어 내는 것이며, 발견은 이미 존재했지만 알려지지 않았던 것을 찾아내는 것이다. 사회 외적 요인으로는 다른 사회와 교류하는 과정에서 생겨나는 문화 전파가 있다.\n\n발명, 발견 또는 전파를 통해 문화 변동이 일어나면 그 결과 사람들의 삶이 한층 풍요로워지기도 하지만, 때로는 여러 부작용이 생겨나기도 한다. 우선 새롭고 이질적인 문화 요소가 등장했을 때 이를 받아들여 기존 문화를 대체하려는 집단과 기존 문화를 유지하려는 집단 간에 갈등이 일어날 수 있다. 또한 외래문화가 문화 변동을 주도하는 경우 고유문화에 대한 자긍심이 훼손되어 사람들이 정체성 혼란을 경험하기도 한다. 한편, 급격한 문화 변동으로 전통 규범과 가치관이 무너졌으나 새로운 규범이 정립되지 않아 개인과 사회가 혼란을 겪는 아노미 현상이 나타날 수 있다. 대개 의식주, 기술 같은 물질문화는 빠르게 변하지만 제도, 규범, 가치관 같은 비물질문화는 상대적으로 변화가 느리다. 그래서 비물질문화가 물질문화의 변동 속도를 따라잡지 못해 부조화 문제가 발생하는데 이를 문화 지체라 한다.\n\n문화 변동으로 생겨나는 문제에 대처하려면, 다양한 문화 요소의 특징과 차이를 이해하고 문화 요소 간 조화와 공존을 위해 노력해야 한다. 더불어 문화 변동에 수동적으로 적응하는 데 만족할 것이 아니라 그것에 대해 성찰하면서 바람직한 문화 변동의 방향을 모색할 수 있어야 한다.",
