            "title": "파란색의 상징적 가치 변천사",
            "content": "오늘날 파란색은 유럽인들이 가장 선호하는 색채이다. 자연에 널리 퍼져 있는 색임에도 파란색은 서양에서 오랫동안 사회·정치·문화·예술 영역에서 그다지 중요하지 않은 색이었다. 고대 그리스 로마인에게 파란색은 무지개에 없는 색이었을 뿐만 아니라, 로마인들의 경우 켈트족이나 게르만족 같은 미개인과 야만인의 색 또는 경계해야 할 색이었다. 붉은색, 흰색, 검은색의 3색 체계를 색의 근본으로 이해한 그리스 로마인들은 장례식 외에는 파란색 옷을 입지 않았다. 파란색은 상(喪)을 당한 암시이자 죽음을 연상시켰다.\n\n파란색이 유럽에서 선호되기 시작한 것은 12세기경부터이다. 부정적 의미를 지녔던 고대의 파란색은 이제 '귀족의 색', '가장 아름다운 색'으로 변화했는데, 여기엔 중세 기독교 성화(聖畵)와의 연관성이 중요했다. 10세기부터 성화 속 파란색은 '신의 현현인 빛'으로 부각되었으며, 12세기에 이르러서는 성당 스테인드글라스의 파란색이 그 바통을 이어받았다. 성스러운 빛이 발하는 색유리의 파란색은 하늘과 빛에 대한 새로운 시각을 형성했다. 동시에 성유리의 파란색은 쉽게 변질되지 않는 특성으로 인해, 흔들리지 않는 믿음의 색 또는 경험한 적 없는 아름답게 빛나는 신성한 색으로 새롭게 인식되었다. 이 과정에서 성화 속의 성모 마리아와 성인들의 의복이 어두운 톤의 파란색에서 밝은 톤의 파란색으로 바뀌었다. 또한 당시 지배적이던 마리아에 대한 열렬한 숭배까지 더해져 파란색은 가장 아름다운 색이 되었다. 이러한 변화는 사회·정치적으로 영향을 미쳐 '모든 색 중 최고의 색'으로서 왕과 귀족들의 사회적 권력을 상징하는 색이 되었다. 나아가 문화·예술 분야에서도 파란색의 미적 가치가 확연히 달라졌다. 13세기에는 염색업자들이 아름다운 청색 염료를 생산해 낼 수 있게 되면서 파란색의 인기 상승에 공헌했다. 이러한 일련의 파란색의 가치 상승은 색의 서열을 완전히 새롭게 편성했다.",
            "source": "미셸 파스투로, 『파랑의 역사』"
