        "title": "문항 2. [무역 확대의 다차원적 영향과 주체별 대응 비교]",
        "questionText": "제시문 (마)의 설명을 바탕으로 제시문 (바)~(아)에 나타난 무역 확대의 긍정적 영향 및 부정적 영향을 서술하고, 부정적 영향에 대한 대응을 비교·분석하시오. (800±100자)",
