            "content": "반도체, 디스플레이, 바이오 산업과 함께 2차전지 산업은 정부가 지정한 4대 국가첨단전략산업 중 하나이다. 2차전지가 전체 수출에서 차지하는 비중이 2012년 0.8%에서 2023년 1.6%로 증가하면서 해당 산업은 차세대 수출 동력으로 각광받고 있으며, 수출입 규모는 매년 급증하는 추세이다. 2차전지의 원료는 흑연, 니켈, 코발트 등 천연광물이 대부분인데, 주요 경쟁국인 중국이 자원적 우위를 점하고 있다. 특히 중국은 2차전지 핵심 광물 중 하나인 흑연의 전 세계 채굴량 중 약 70%(2022년 기준)를 차지하고 있다. 자원 빈국인 우리나라는 2차전지의 핵심 원료인 흑연을 주로 중국으로부터 수입하고 있다.\n\n2차전지 시장의 확대로, 국내 기업은 상대적 경쟁력 확보를 위하여 배터리의 용량, 충전속도, 안정성 등 다방면에서 제품 성능을 비약적으로 개선하기 위한 연구개발 투자를 지속하고 있다. 산업통상자원부 역시 전기차, 전력망 등 다른 분야로의 파급력이 큰 2차전지 산업의 활성화를 위하여 대규모 연구개발 예산을 지원하고, 수입 광물의 자립화를 위한 국내 기업의 투자가 원활히 이뤄지도록 특화단지에 도로, 전력, 용수시설 구축 등을 지원할 예정이다.\n\n최근 OO배터리(주) 전략팀에 고액 연봉으로 스카우트된 김부장은 얼마 전 중국에서 흑연 채굴량 과다로 지하수 오염 등 채굴지의 자연 생태계 파괴가 심각하다는 뉴스와 함께, 중국 상무부가 자국 내 환경 및 첨단산업 보호를 위해 흑연의 채굴량을 줄이고 해외 수출을 통제한다는 보도를 접했다. 이에 김부장은 국내 공장의 흑연 재고 추가비축을 요청하고, 구매팀을 통해서는 아프리카 국가 등 흑연 수입 대체국가를 물색하고 있다. 무엇보다도 김부장은 정부가 중국과 핵심 광물의 수급 안정화를 위한 외교적 노력을 더 강화해 주기를 기대하고 있다.",
            "source": "한국무역협회 보고서 / 연합뉴스 외 기사 재구성 (2차전지 흑연 공급망 사례)"
