        "modelAnswer": "(바)에서 정부의 유학생 유치 노력은 A국 교육 수출 및 유학생 유치산업의 활성화를 통하여 국내총생산 증가, 고용 창출 및 주택 임대차 시장의 성장 등을 이끌었다. 그러나 유학생 유입으로 인한 인종적, 문화적 갈등과 임대료 폭등 등 부작용이 발생하였다.\n\n(사)의 경우 B국의 생산 요소인 노동 수출을 통한 무역 확대 추진으로 파견 인력과 가족의 소득 및 국내총생산 증가 등 긍정적 영향이 있었으나, 고급인력의 비효율적 활용과 파견 인력 개인의 인권침해라는 결과가 발생하였다.\n\n(아)에서 정부의 2차전지 산업 지원정책은 관련 종사자의 소득 증대, 연구개발 활성화를 통한 기업의 경쟁력 강화와 연관 산업 및 첨단기술 발전 등 모든 경제 주체에게 이익이 되었다. 다만, 특정 국가에 대한 지나친 자원 의존으로 국내 경제가 타국 경제 상황에 민감하게 반응한다는 문제가 있다.\n\n(바)~(아)를 비교하면, 모두 국제무역 확대를 위하여 정부가 관련 산업을 특화하고, 그로 인한 부정적 영향이 경제 및 사회 제반 분야에서 나타난 공통점이 있다. 경제적으로는 (바)와 (아)에서 각각 임대료 폭등 및 자원 의존도 심화가, 사회문화적으로는 (바)의 인종차별과 (사)의 인권침해가, 환경적으로는 (아)의 수질오염 발생이 그 구체적인 사례이다. 한편, 부정적 영향에 대한 대응 주체가 (바)는 국가(A국 및 타국 정부) 위주이며, (사)는 민간 사회단체라는 점이 주요 차이점이다. 반면 (아)는 자원 의존도 심화 문제 해결을 위하여 가계, 기업, 정부 등 관련 경제주체 모두가 대응하는 양상을 보여준다. 또한 각 제시문에서 무역 확대의 부작용 이후 국가적 대응이 (바), (사), (아) 순서로 일부 후퇴, 특별한 대응 없음, 정책적·외교적 노력 지속 등으로 각각 상이하다."
