            "content": "“상감마마, 마음을 든든히 하시오.”\n알천은 떨리는 소리로 이렇게 아뢰었다.\n“아니, 이 몸의 갈 날이 이르렀소. 이 몸이 철없는 어린 여자의 몸으로 임금이 된 지 팔 년 동안 큰 허물이 없이 지낸 것은 다 알천 상대등의 충의의 힘이오. 이 몸이 죽은 뒤의 일은 다 알아서 하시오.”\n왕은 이렇게 말씀하셨다. 알천은 무어라고 아뢸 바를 몰라서 다만 머리를 조아릴 뿐이었다. 왕은 다시 말을 이으시며,\n“고구려와 백제가 다 우리나라를 엿보고 있으니 앞으로 나라에 어려운 일이 많을 것 같소. 춘추는 당나라의 힘을 빌려 백제와 고구려를 멸하려 하나, 이것은 외인을 불러서 형제를 치려 하는 것과 같으므로 이 몸이 허락지 아니하였으니, 차라리 백제와 고구려에 사신을 보내어 서로 화친할 것을 말하고 세 나라가 한곳에 모여 서로 맹약함이 좋을까 하오. 행여 당병을 이 땅에 끌어들이지는 마오.” 하시는 유칙이 계시었다.",
