            "content": "삼국 말기에는 상호 교류와 영역 변동 등을 통해 삼국의 주민 간에 풍습·제도·의복 등 생활 양태에서의 동질화도 진전되어 갔다. 그래서 이 시기 제3국 사람들이 삼국의 주민을 같은 족속으로 분류하여, 이를 삼한(三韓)이라 하는 ‘이름 붙이기’를 하기도 하였다. 하지만 삼국 주민 간의 동족 의식은 통일 전쟁의 마지막 단계인 668년 이후, 당과의 전쟁을 거치는 과정에서 싹트기 시작했다고 여겨진다. 그리고 이는 현실적인 필요 때문에 신라 조정의 주도하에 전면에 내세워졌다. 삼국인이 같은 한(韓)에 속한 세 집단으로서 이제 하나가 되었다는 의식이 그것이다. 삼한이란 새로운 ‘이름 붙이기’와 ‘이름 부르기’가 합치하는 양상의 일면을 보인 것이다.\n\n이어 통일신라기 2백여 년 동안 중앙집권적 체제하에서 당시 사람들의 삶의 양식에 상당한 공통성이 형성되었을 것으로 여겨진다. 신라 영역 내의 주민들이 교류하면서 문화적 융합도 진행되었는데, 서민 사이에 널리 퍼져 나간 불교가 주요한 역할을 하였다. 그 과정에서 동족 의식 또한 확산되었다. 그러나 정치·경제적인 면에서 소외되었던 백제·고구려 유민들에게는 그것은 피동적인 귀속 의식 이상은 아니었고, 내면의 한편에는 삼국 유민 의식이 자리 잡고 있었다. 그런 면이 신라 말 농민 봉기의 파장에 편승하여 후삼국의 정립으로 나타났다.",
