            "id": "[바]",
            "title": "불완전 경쟁 시장의 독과점과 불공정 행위",
            "content": "불완전 경쟁 시장이란 시장 참여자 간에 자유롭고 공정한 경쟁이 이루어지지 않는 시장을 말한다. 공급자가 하나 또는 소수인 독점 또는 과점 시장이 이에 해당한다. 독과점 기업은 자신에게 가장 유리한 가격을 책정함으로써 경쟁시장에서보다 더 큰 이윤을 얻을 수 있지만, 소비자는 자신이 누려야 할 잉여의 상당 부분을 기업의 이윤으로 흡수당하게 된다. 소수 기업이 시장을 분할 지배하고 있는 과점 시장에서는 기업이 가격 담합을 통해 경쟁을 회피하는 현상이 종종 발생한다. 이 경우 담합 기업은 품질이나 가격 경쟁을 할 필요 없이 편하게 이윤을 얻을 수 있지만, 소비자는 차별성이 없는 비슷한 상품에 대해 비싼 가격을 지불해야 하는 불이익을 당하게 된다. 경제적으로 우위에 있는 기업이 자신의 우월한 지위를 이용하여 상대적으로 약자인 거래 상대방에게 불리한 거래 조건을 강요하거나, 제품에 대한 허위 정보로 상대방을 속이는 행위도 시장 실패를 가져오는 불공정 행위에 해당된다. 불완전 경쟁 시장에서 나타나는 이러한 불공정 행위는 자원 배분의 효율성을 저해하는 시장 실패의 원인일 뿐만 아니라 다른 사람이 누려야 할 경제적 이득을 빼앗는 불법적이고 비윤리적인 행위이다.",
